<style>:root{color-scheme:dark;--bg:#101114;--panel:#191b20;--line:#2a2d34;--text:#f4f5f7;--muted:#969ba6;--accent:#d8ff45}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 Inter,system-ui,sans-serif}.shell{max-width:1000px;margin:auto;padding:0 24px}header{height:76px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.brand{font-size:21px;font-weight:900;letter-spacing:.12em;color:white;text-decoration:none}.brand span{color:var(--accent)}a{color:inherit;text-decoration:none}.muted{color:var(--muted)}h1{font-size:38px;letter-spacing:-.04em;margin:45px 0 8px}.button{display:inline-block;background:var(--accent);color:#15170d;padding:10px 15px;border:0;border-radius:8px;font-weight:850;cursor:pointer}.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:20px;margin:14px 0}.card h2{margin:0 0 5px}.success{color:var(--accent)}.error{color:#ff9696}.member{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--line)}input{background:#101114;border:1px solid #373b44;border-radius:8px;padding:10px;color:white;min-width:0}.inline{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.small{font-size:12px;color:var(--muted)}@media(max-width:600px){.shell{padding:0 16px}}/* ARENA-X-MOTION-POLISH */

body{background-image:radial-gradient(ellipse at 85% 5%,#d8ff4510,transparent 34%)}header{animation:fadeDown .5s both}main{animation:rise .55s .08s both}.card{transition:transform .22s,border-color .22s,box-shadow .22s;animation:rise .55s both}.card:hover{transform:translateY(-4px);border-color:#59613b;box-shadow:0 16px 38px #0005}.button{transition:transform .2s,box-shadow .2s}.button:hover{transform:translateY(-2px);box-shadow:0 8px 22px #d8ff4530}.member{transition:background .2s}.member:hover{background:#ffffff05}input:focus{outline:1px solid var(--accent);border-color:var(--accent)}@keyframes fadeDown{from{opacity:0;transform:translateY(-10px)}to{opacity:1;transform:none}}@keyframes rise{from{opacity:0;transform:translateY(15px)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important}}
